    Bug 1985147 - Use the mail secure icon for EWS accounts in popup and folders. r=tobyp


    Apply the correct email envelope icon to EWS accounts:
    - Get Messages right click menu popup in folder pane.
    - Get Messages right click menu popup in unified toolbar.
    - Folder pane.

    Differential Revision: https://phabricator.services.mozilla.com/D262489

diff --git a/mail/themes/shared/mail/about3Pane.css b/mail/themes/shared/mail/about3Pane.css
index ef437fe23f7..27bff79b29f 100644
--- a/mail/themes/shared/mail/about3Pane.css
+++ b/mail/themes/shared/mail/about3Pane.css
@@ -273,11 +273,11 @@ body {
       --icon-color: var(--primary);
     }

-    &:is([data-server-type="imap"], [data-server-type="pop3"]) > .container > .icon {
+    &:is([data-server-type="imap"], [data-server-type="pop3"], [data-server-type="ews"]) > .container > .icon {
       background-image: var(--icon-mail);
     }

-    &:is([data-server-type="imap"], [data-server-type="pop3"])[data-server-secure="true"]
+    &:is([data-server-type="imap"], [data-server-type="pop3"], [data-server-type="ews"])[data-server-secure="true"]
       > .container > .icon {
       background-image: var(--icon-mail-secure);
     }
diff --git a/mail/themes/shared/mail/serverMenuItems.css b/mail/themes/shared/mail/serverMenuItems.css
index d3899409078..05435aa91a2 100644
--- a/mail/themes/shared/mail/serverMenuItems.css
+++ b/mail/themes/shared/mail/serverMenuItems.css
@@ -3,11 +3,11 @@
  * file, You can obtain one at http://mozilla.org/MPL/2.0/. */

 menuitem.server {
-  &:is([data-server-type="imap"], [data-server-type="pop3"]) {
+  &:is([data-server-type="imap"], [data-server-type="pop3"], [data-server-type="ews"]) {
     --menuitem-icon: var(--icon-mail);
   }

-  &:is([data-server-type="imap"], [data-server-type="pop3"])[data-server-secure="true"] {
+  &:is([data-server-type="imap"], [data-server-type="pop3"], [data-server-type="ews"])[data-server-secure="true"] {
     --menuitem-icon: var(--icon-mail-secure);
   }
